export const courseChallenges = levels.flatMap((level, levelIndex) =>
  level.lessons.flatMap((lesson, lessonIndex) => lesson.questions.map((question, questionIndex) => {
    const correct = (levelIndex + lessonIndex + questionIndex) % 2;
    const good = { ...question.good, label: question.good.heading, variant: 'good' };
    const bad = { ...question.bad, label: question.bad.heading, variant: 'bad' };
    return {
      id: `${lesson.id}-${questionIndex + 1}`,
      lessonId: lesson.id,
      topic: lesson.topic,
      title: question.principle,
      prompt: question.prompt,
      difficulty: questionIndex < 2 ? 'Beginner' : 'Intermediate',
      principle: question.principle,
      explanation: question.explanation,
      takeaway: question.takeaway,
      options: correct === 0 ? [good, bad] : [bad, good],
      correct,
      visual: 'course-concept',
    };
  }))
);

export const courseLevels = levels.map(({ id, title, description, lessons }) => ({
  id, title, description,
  lessons: lessons.map(({ id, title, description, icon }) => ({
    id, title, description, icon,
    challengeIds: courseChallenges.filter(challenge => challenge.lessonId === id).map(challenge => challenge.id),
  })),
}));

export const courseLessons = courseLevels.flatMap(level => level.lessons);
export const courseLessonById = Object.fromEntries(courseLessons.map(lesson => [lesson.id, lesson]));
export const courseChallengeById = Object.fromEntries(courseChallenges.map(challenge => [challenge.id, challenge]));
